import * as hono_types from 'hono/types';
import { Hono } from 'hono';
import { FileNode, AgentEvent, Beat } from '@agent-theatre/core';

interface TheatreOptions {
    cwd: string;
    repoId: string;
    files: FileNode[];
    /** Directory of the built web bundle (index.html + assets). Optional in tests. */
    webDir?: string;
    /** Where to write the port file. Default ~/.agent-theatre */
    home?: string;
    /** No hook events for this long while a session is open → "lost" signal. */
    lostAfterMs?: number;
}
/**
 * The local theatre. Loopback only. Receives hook payloads, directs them into
 * beats, and streams events + beats to the browser. Serves the web bundle and
 * replay payloads. Never logs or forwards tool input/output: the hook payload
 * is reduced to AgentEvents at the door and discarded.
 */
declare class Theatre {
    private readonly opts;
    readonly app: Hono<hono_types.BlankEnv, hono_types.BlankSchema, "/">;
    private server;
    private wss;
    private live;
    private signal;
    /** The most recent cwd of a Claude Code session that is NOT this repo (so an empty stage can point the person there). */
    private elsewhere;
    private readonly openSessions;
    private timer;
    port: number;
    constructor(opts: TheatreOptions);
    private routes;
    /** Append events to the live session, direct them, and broadcast. */
    ingest(events: AgentEvent[]): Beat[];
    /** In-process subscribers (the VS Code extension relays these to its webview). */
    readonly listeners: Set<(msg: unknown) => void>;
    private broadcast;
    listen(port?: number): Promise<number>;
    close(): Promise<void>;
    /** The live scene as /api/scene returns it. */
    scene(): unknown;
    get url(): string;
    get name(): string;
}

/** The repo's file tree as FileNodes. Counts lines only; never keeps contents. Bounded for huge repos. */
declare function scanRepo(root: string, opts?: {
    maxFiles?: number;
    maxBytesForLoc?: number;
}): FileNode[];
/** Stable repo identity: git remote URL when available, else the absolute path. */
declare function repoIdFor(root: string): string;

interface SessionInfo {
    id: string;
    path: string;
    mtime: number;
    bytes: number;
    title: string;
}
/** Sessions for a repo, newest first, with a human title from the transcript's own title rows (local picker only; never into events). */
declare function listSessions(cwd: string, env?: NodeJS.ProcessEnv): SessionInfo[];
/** Title = latest `aiTitle` row, else the latest `lastPrompt` row (trimmed), else the id. Reads at most the last 256 KB. */
declare function sessionTitle(path: string): string;

interface InstallPaths {
    settings: string;
    home: string;
    script: string;
    backup: string;
}
declare function installPaths(env?: NodeJS.ProcessEnv): InstallPaths;
/** Writes the hook script, then merges our entries into settings.json (backup first). Idempotent. */
declare function installHooks(paths?: InstallPaths): {
    changed: boolean;
    backup: string | null;
};
/** Removes only our entries. Leaves the backup file in place for the user. */
declare function uninstallHooks(paths?: InstallPaths): {
    changed: boolean;
};
declare function hooksStatus(paths?: InstallPaths): {
    installed: boolean;
    scriptPresent: boolean;
    settings: string;
};

export { type InstallPaths, type SessionInfo, Theatre, type TheatreOptions, hooksStatus, installHooks, installPaths, listSessions, repoIdFor, scanRepo, sessionTitle, uninstallHooks };
